const User = require('./User');  // Import the User class

class UsersList {
    
    constructor() {
        this.users = [];
    }
    getUsers() {
        return this.users.map(user => new User(user.id,user.firstName, user.lastName, user.email, user.password, user.gender, user.picture));
    }

    addUser(user) {
        this.users.push(user);
    }
}
const usersList = new UsersList();

const user = {
    id: '1',
    firstName: 'John',
    lastName: 'Doe',
    email: 'user1',
    password: 'pass',
    gender: 'male',
    picture: 'picture.jpg'
};

usersList.addUser(user);

console.log(usersList.users);

